; Every pattern byte $F0: the left four pixels ink, the right four paper. Every
; colour byte a pair of colours of its own, from gen22.py, so that each strip
; of 8 x 1 on the screen shows which colour byte the VDP took for it.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $0000        ; patterns: $F0
        ld bc, 6144
pat:    ld a, $F0
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, pat
        VRAM_WRITE $2000        ; colours: 6,144 bytes from the table
        ld hl, table
        ld c, VDP_DATA
        ld d, 24                ; 24 x 256
col:    ld b, 0
        otir
        dec d
        jr nz, col
        VDP_REG 1, $C0          ; the display on
done:   jr done
